from collections import deque

def components(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   col=g[r][c]
   if not col or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for p in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     a,b=p
     if 0<=a<h and 0<=b<w and p not in seen and g[a][b]==col:
      seen.add(p); q.append(p)
   out.append((col,cells))
 return out

def slide(g):
 h,w=len(g),len(g[0]); objs=components(g)
 poses=[set(cells) for col,cells in objs]
 while True:
  occupied=set().union(*poses); moves=[]
  for i,p in enumerate(poses):
   targets={(r,c+1) for r,c in p}
   if any(c+1>=w for r,c in p): continue
   others=occupied-p
   if not targets & others: moves.append(i)
  if not moves: break
  # simultaneous movement
  for i in moves: poses[i]={(r,c+1) for r,c in poses[i]}
 out=[[0]*w for _ in range(h)]
 for (col,_),p in zip(objs,poses):
  for r,c in p: out[r][c]=col
 return out,[(col,sorted(orig),sorted(pos)) for (col,orig),pos in zip(objs,poses)]

